  "rung_purposes": [
    {
      "rung": 1,
      "purpose": "Initialize station setpoints: fill threshold D122, max drop D120, overpressure limit D123."
    },
    {
      "rung": 2,
      "purpose": "Detect pack pressure sensor wire break or under-range condition (< -500)."
    },
    {
      "rung": 3,
      "purpose": "Latch overpressure alarm M291 if pack pressure exceeds threshold D123."
    },
    {
      "rung": 4,
      "purpose": "Latch supply air pressure low alarm M293 if air drops while station is busy."
    },
    {
      "rung": 5,
      "purpose": "Reset latched alarms M290, M291, and M293 upon pressing fault reset PB X1."
    },
    {
      "rung": 6,
      "purpose": "Summarize station fault state into M299 and drive fault beacon Y25."
    },
    {
      "rung": 7,
      "purpose": "Energize vent valve Y22 via manual vent PB X25 in manual mode."
    },
    {
      "rung": 8,
      "purpose": "Start auto cycle at Step 1 (Clamp) when pallet arrives without active faults."
    },
    {
      "rung": 9,
      "purpose": "Advance Step 1 (Clamp) to Step 2 (Fill) once clamp closed limit is confirmed."
    },
    {
      "rung": 10,
      "purpose": "Run fill timeout timer T21 during Step 2 (Fill)."
    },
    {
      "rung": 11,
      "purpose": "Latch fill timeout alarm M290 if timer T21 elapses."
    },
    {
      "rung": 12,
      "purpose": "Advance Step 2 (Fill) to Step 3 (Stabilise) once target pressure D122 is reached."
    },
    {
      "rung": 13,
      "purpose": "Run stabilisation timer T22 during Step 3 (Stabilise)."
    },
    {
      "rung": 14,
      "purpose": "Capture initial test pressure D110 when test timer T23 triggers."
    },
    {
      "rung": 15,
      "purpose": "Advance Step 3 (Stabilise) to Step 4 (Test) upon completion of timer T22."
    },
    {
      "rung": 16,
      "purpose": "Run leak test window timer T23 during Step 4 (Test)."
    },
    {
      "rung": 17,
      "purpose": "Capture final pressure D111 and compute pressure drop D112 when T23 elapses."
    },
    {
      "rung": 18,
      "purpose": "Compare pressure drop D112 against max limit D120 to latch PASS M210 or FAIL M211."
    },
    {
      "rung": 19,
      "purpose": "Advance Step 4 (Test) to Step 5 (Vent) when test timer T23 completes."
    },
    {
      "rung": 20,
      "purpose": "Abort cycle on fault M299 by forcing step sequence to Step 5 (Vent) and latching FAIL."
    },
    {
      "rung": 21,
      "purpose": "Run vent timer T200 during Step 5 (Vent)."
    },
    {
      "rung": 22,
      "purpose": "Advance Step 5 (Vent) to Step 6 (Unclamp) when pressure is low and vent timer expires."
    },
    {
      "rung": 23,
      "purpose": "Advance Step 6 (Unclamp) to Step 7 (Complete) once clamp open limit is confirmed."
    },
    {
      "rung": 24,
      "purpose": "Clear cycle busy and complete flags when pallet departs test position X23."
    },
    {
      "rung": 25,
      "purpose": "Energize clamp solenoid Y20 throughout steps 1 to 5."
    },
    {
      "rung": 26,
      "purpose": "Energize fill valve Y21 during Step 2 when no fault is present."
    },
    {
      "rung": 27,
      "purpose": "Energize vent valve Y22 during Step 5 (Vent) or on overpressure alarm M291."
    },
    {
      "rung": 28,
      "purpose": "Output PASS (Y23) or FAIL (Y24) result to line controller during Step 7."
    },
    {
      "rung": 29,
      "purpose": "End of ladder program execution."
    }
  ],
  "suspicious": [
